// Assets Fallback Base64 para garantir carregamento 100% Ã  prova de falhas
const SODIPROM_ASSETS = {
  "sodiprom-logo50anos.png": "data:image/png;base64,",
  "sodiprom-logo.png": "data:image/png;base64,",
  "logo-icon-sodiprom.png": "data:image/png;base64,"
};

function fallbackImg(el, name) {
  if (SODIPROM_ASSETS[name]) {
    el.src = SODIPROM_ASSETS[name];
    el.removeAttribute('onerror');
  }
}